// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint64 ts, address player) public {
        vm.assume(player != address(0));
        vm.assume(player != address(c));
        vm.warp(ts);
        uint256 amount = 10;
        vm.deal(player, amount);
        vm.prank(player);
        c.play{value: amount}();

        // Deterministic prediction of the contract's own lottery draw:
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        if (random == 0) {
            // On a win the pot must be fully reset to 0 after payout.
            assertTrue(c.pot() == 0, "pot must be 0 after a winning play");
        } else {
            // On a loss the pot accumulates the ticket amount.
            assertTrue(c.pot() == amount, "pot must hold accumulated tickets after a losing play");
        }
    }
}

