pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // set the environment that feeds the on-chain randomness
        vm.warp(ts);
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;

        // fund the contract so every internal transfer can succeed, fund the player for the ticket
        vm.deal(address(c), 1e18);
        vm.deal(actor, 100);

        bool ok;
        vm.prank(actor);
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a correctly priced play never reverts, whatever the randomness is.
        // In C the pot is credited before the winning payout (payout = old pot + 10 - 1 >= 0),
        // so ok is true for every admissible input. In M a winning draw on a fresh pot computes
        // pot - FEE = 0 - 1, underflowing and reverting: the fuzzer finds ts with random == 0.
        assertTrue(ok, "play with exact ticket price must not revert");
    }
}

