pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, uint256 diff, address player) public {
        vm.assume(player != address(0));
        vm.assume(player != address(this));
        vm.assume(player != address(c));

        vm.warp(ts);
        vm.roll(diff);
        bool win = uint256(keccak256(abi.encodePacked(ts, diff))) % 2 == 0;

        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        if (win) {
            // A winning play always drains the contract: fee to bank + whole pot to player.
            // Reference: balance == 0. Mutant re-adds the 10-wei ticket, leaving balance == 10.
            assertTrue(address(c).balance == 0, "winning play must drain the contract balance");
        }
    }
}

