pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        uint256 amount = 10; // admissible ticket price fixed by require(msg.value == TICKET_AMOUNT)
        uint potBefore = c.pot();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.play{value: amount}();

        // General rule: after every successful play, the pot grew by exactly the ticket amount paid.
        assertTrue(c.pot() == potBefore + amount);
    }
}

